/// <summary>Manage user roles, as admin.</summary>
[TestFixture]
[Category("manage-roles")]
[Category("admin")]
public class ManageRolesAdminTests : PageTest
{
    public override BrowserNewContextOptions ContextOptions() => new()
    {
        BaseURL = Environment.GetEnvironmentVariable("BASE_URL") ?? "http://127.0.0.1:5173",
        // Signed-in session for admin; see README.md.
        StorageStatePath = Environment.GetEnvironmentVariable("TESSA_AUTH_ADMIN") ?? ".auth/admin.json",
    };

    /// <summary>Proves an admin can change another user's role and the change is saved, not just shown.</summary>
    [Test]
    [Description("Admin promotes a viewer to editor")]
    [Property("SeedProfile", "admin-heavy")]
    [Category("happy-path")]
    public async Task AdminChangesRole()
    {
        await Page.GotoAsync("/admin/users");
        // 1. Set the viewer's role to editor
        await Page.GetByTestId("role-select-viewer").SelectOptionAsync("editor");
        // 2. Save the viewer's role
        await Page.GetByTestId("role-save-viewer").ClickAsync();
        // 3. Reload the Users page
        await Page.GotoAsync("/admin/users");
        // 4. The viewer's role is now editor
        await Expect(Page.GetByTestId("role-select-viewer")).ToHaveValueAsync("editor");
    }

    /// <summary>Proves the signed-in admin's own row cannot be edited, so an admin cannot demote themselves.</summary>
    [Test]
    [Description("Admin cannot change their own role")]
    [Property("SeedProfile", "admin-heavy")]
    [Category("edge")]
    public async Task AdminCannotChangeOwnRole()
    {
        await Page.GotoAsync("/admin/users");
        // 1. The admin's own role select is disabled
        await Expect(Page.GetByTestId("role-select-admin")).ToBeDisabledAsync();
        // 2. The admin's own Save button is disabled
        await Expect(Page.GetByTestId("role-save-admin")).ToBeDisabledAsync();
        // 3. Another admin's role can still be edited
        await Expect(Page.GetByTestId("role-select-admin2")).ToBeEnabledAsync();
    }
}

