        await Expect(Page.GetByTestId("nav-admin-users")).ToHaveCountAsync(0);
        // 2. Go to the Users page directly
        await Page.GotoAsync("/admin/users");
        // 3. A permission error is shown
        await Expect(Page.GetByRole(AriaRole.Alert)).ToContainTextAsync("permission");
    }
